"use client"

import Image from "next/image"

import { cn } from "@/lib/utils"

import type { HotspotImageProps } from "./types"

export function HotspotImage({
  src,
  alt,
  width,
  height,
  children,
  className,
}: HotspotImageProps) {
  return (
    <div
      aria-label={`Shoppable image: ${alt}`}
      className={cn("relative w-full overflow-x-auto overflow-y-hidden", className)}
      role="region"
    >
      <div className="relative inline-block" style={{ width: `${width}px` }}>
        <Image
          alt={alt}
          className="block"
          height={height}
          priority={false}
          sizes={`${width}px`}
          src={src}
          width={width}
        />
        {children}
      </div>
    </div>
  )
}

"use client"

import { Plus } from "lucide-react"

import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover"
import { cn } from "@/lib/utils"

import type { HotspotPinProps } from "./types"

const pinBaseClasses =
  "absolute inline-flex items-center justify-center rounded-full shadow-sm transition-[background-color,box-shadow,filter] hover:brightness-95 focus-visible:outline-none focus-visible:ring-3 focus-visible:ring-ring/50 motion-reduce:transition-none"

const pinVariantClasses = {
  plus:
    "size-8 border-[3px] border-black/70 bg-background text-foreground hover:bg-accent dark:border-white/70",
  dot: "size-5 rounded-full border-[3px] border-background/80 bg-primary text-primary-foreground",
} satisfies Record<NonNullable<HotspotPinProps["variant"]>, string>

export function HotspotPin(props: HotspotPinProps) {
  const { x, y, variant = "plus", label, children, className } = props

  return (
    <Popover>
      <PopoverTrigger
        aria-label={label ?? `Hotspot at ${x}%, ${y}%`}
        className={cn(
          pinBaseClasses,
          pinVariantClasses[variant],
          className
        )}
        style={{
          left: `${x}%`,
          position: "absolute",
          top: `${y}%`,
          transform: "translate(-50%, -50%)",
        }}
        type="button"
      >
        {variant === "plus" ? <Plus aria-hidden="true" className="size-4" /> : null}
      </PopoverTrigger>
      <PopoverContent
        align="center"
        className="max-w-[90vw] w-auto p-0 has-[[data-slot=card]]:overflow-hidden has-[[data-slot=card]]:rounded-xl has-[[data-slot=card]]:bg-transparent"
        side="top"
      >
        {children}
      </PopoverContent>
    </Popover>
  )
}

import { cn } from "@/lib/utils"

import type { HotspotTooltipProps } from "./types"

export function HotspotTooltip({
  title,
  description,
  className,
}: HotspotTooltipProps) {
  return (
    <div className={cn("max-w-xs p-4", className)}>
      <h3 className="mb-1 text-sm font-semibold">{title}</h3>
      <p className="text-sm text-muted-foreground">{description}</p>
    </div>
  )
}

import { ArrowRight } from "lucide-react"

import { cn } from "@/lib/utils"

import type { HotspotLinkProps } from "./types"

export function HotspotLink({
  label,
  href,
  target,
  className,
}: HotspotLinkProps) {
  return (
    <a
      className={cn(
        "flex items-center gap-2 rounded-md px-4 py-3 transition-colors hover:bg-accent motion-reduce:transition-none",
        className
      )}
      href={href}
      rel={target === "_blank" ? "noopener noreferrer" : undefined}
      target={target}
    >
      <span className="text-sm font-medium">{label}</span>
      <ArrowRight aria-hidden="true" className="h-4 w-4" />
    </a>
  )
}

import type * as React from "react"

export type Currency = "EUR" | "USD" | "GBP" | "SEK"

export type Price = {
  /** Amount in minor units (cents). */
  amount: number
  currency: Currency
  /** Optional compare-at price for strikethrough display. In minor units. */
  compareAt?: number
}

export type Rating = {
  /** 0–5 inclusive. */
  value: number
  /** Number of reviews. */
  count: number
}

export type ProductBadge = {
  label: string
  variant?: "default" | "sale" | "new"
}

export type ProductImage = {
  src: string
  alt: string
}

export type VariantOption = {
  /** Display label (e.g., "Cream", "Medium"). */
  label: string
  /** Machine value (e.g., "cream", "m"). */
  value: string
  /** CSS color value for type="swatch" (e.g., "#f5f0e8", "oklch(...)"). */
  swatch?: string
  /** If true, option renders but is not selectable. */
  disabled?: boolean
}

export type ProductVariant = {
  /** Unique identifier used as the key in SelectedVariants. */
  id: string
  /** Display label (e.g., "Color", "Size"). */
  name: string
  /** Input type for rendering. */
  type: "swatch" | "pills" | "select" | "slider" | "checkbox" | "radio"
  /** If true, user must select a value before Add to Cart is enabled. Default: false. */
  required?: boolean
  /** Option list. For type="slider", this is unused. */
  options: VariantOption[]
  /** Optional config specific to type="slider". */
  sliderConfig?: {
    min: number
    max: number
    step: number
    unit?: string
  }
}

export type Product = {
  id: string
  title: string
  description?: string
  category?: string
  /** Array of product images. Must contain at least one entry. First image is the default. */
  images: ProductImage[]
  price: Price
  rating?: Rating
  badge?: ProductBadge
  href?: string
  variants?: ProductVariant[]
}

export type SelectedVariants = Record<string, string | string[] | number>

export type ProductCardLayout =
  | "vertical"
  | "horizontal"
  | "horizontal-detailed"
export type ProductCardVariantsMode = "none" | "inline" | "overlay"

export type ProductCardProps = {
  product: Product
  layout?: ProductCardLayout
  variants?: ProductCardVariantsMode
  /** Which slideshow navigation controls to render when product has multiple images. Default: "both". */
  slideshowControls?: "arrows" | "dots" | "both" | "none"
  showWishlist?: boolean
  showRating?: boolean
  showQuickView?: boolean
  onAddToCart?: (args: {
    productId: string
    selectedVariants?: SelectedVariants
  }) => void
  onWishlistToggle?: (productId: string) => void
  onQuickView?: (productId: string) => void
  className?: string
}

export type HotspotPinVariant = "plus" | "dot"

export type HotspotImageProps = {
  /** Image source. */
  src: string
  /** Image alt text. Required for accessibility. */
  alt: string
  /** Natural width in pixels. Required — matches next/image API. */
  width: number
  /** Natural height in pixels. Required — matches next/image API. */
  height: number
  /** HotspotPin children. */
  children: React.ReactNode
  /** Optional className for the outer scrollable wrapper. */
  className?: string
}

export type HotspotPinProps = {
  /** Horizontal position as a percentage of image width (0–100). */
  x: number
  /** Vertical position as a percentage of image height (0–100). */
  y: number
  /** Visual style of the pin. Default: "plus". */
  variant?: HotspotPinVariant
  /** Accessible label for the pin button. Defaults to "Hotspot at X%, Y%" if not provided. */
  label?: string
  /** Popover content rendered when the pin is activated. */
  children: React.ReactNode
  /** Optional className for the pin button. */
  className?: string
}

export type HotspotTooltipProps = {
  /** Title displayed at top of the tooltip. */
  title: string
  /** Description text below the title. */
  description: string
  /** Optional className for the tooltip container. */
  className?: string
}

export type HotspotLinkProps = {
  /** Link label. */
  label: string
  /** Link href. */
  href: string
  /** Optional target (e.g., "_blank"). */
  target?: React.HTMLAttributeAnchorTarget
  /** Optional className for the link container. */
  className?: string
}

import type { Price } from "./types"

/**
 * Formats a Price object as a localized currency string.
 * Uses `en-US` locale for predictability; consumers can wrap for their own locale.
 */
export function formatPrice(price: Price): string {
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: price.currency,
  }).format(price.amount / 100)
}
